fs.mkdirSync(path.join(root, 'orlando', 'universal'), { recursive: true });

function writeHtml(file, html) {
  fs.writeFileSync(file, html.replace(/&(?![A-Za-z][A-Za-z0-9]+;|#\d+;|#x[0-9A-Fa-f]+;)/g, '&amp;'));
}

