function crumbs(items) {
  return `<div class="dw-breadcrumbs"><a href="/index.html">Home</a><span>›</span><a href="/orlando/index.html">Orlando</a><span>›</span>${items.map((item, i) => i === items.length - 1 ? `<span aria-current="page">${item.label}</span>` : `<a href="${item.href}">${item.label}</a><span>›</span>`).join('')}</div>`;
}

function page({ title, description, canonical, eyebrow, heading, lead, body, itemLabel, itemHref = '', hero = true }) {
  const item = itemLabel ? [{ label: itemLabel, href: itemHref }] : [];
  return `<!doctype html>
<html lang="en"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#123f5a">
<meta name="description" content="${description}"><link rel="canonical" href="https://countrymantravels.com${canonical}">
<title>${title} | Countryman Travels</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&amp;family=Source+Serif+4:opsz,wght@8..60,600;8..60,700&amp;display=swap" rel="stylesheet">
<link rel="stylesheet" href="/css/style.css?v=20260802f"><link rel="stylesheet" href="/css/home.css?v=20260809a"><link rel="stylesheet" href="/css/disney-world.css?v=20260817b"><link rel="stylesheet" href="/css/site-shell.css?v=20260802a">
</head><body class="home-page dw-page">${nav}<main id="main">${crumbs(item)}${hero ? `<section class="dw-page-hero"><div><p class="dw-eyebrow">${eyebrow}</p><h1>${heading}</h1><p>${lead}</p></div><aside><strong>Living companion</strong><span>Book strategy from the guide. Current links and decision tools here.</span><small>Last editorial review: August 2026</small></aside></section>` : ''}${body}</main>${footer}<script src="/js/site-shell.js?v=20260802a" defer></script></body></html>`;
}

function section(title, intro, content, id = '') {
  return `<section class="dw-section"${id ? ` id="${id}"` : ''}><div class="dw-section-heading"><div><p class="dw-eyebrow">Plan the decision</p><h2>${title}</h2></div><p>${intro}</p></div>${content}</section>`;
}

function cards(items) {
  return `<div class="dw-card-grid">${items.map(item => `<article class="dw-card">${item.photo ? `<figure class="dw-card-photo"><img src="${item.photo.src}" alt="${item.photo.alt}" loading="lazy" decoding="async"><figcaption>Photo: <a href="${item.photo.sourceUrl}" target="_blank" rel="noopener">${item.photo.photographer}</a></figcaption></figure>` : ''}${item.kicker ? `<span>${item.kicker}</span>` : ''}<h3>${item.title}</h3><p>${item.text}</p>${item.href ? `<a href="${item.href}">${item.link || 'Open guide'} →</a>` : ''}</article>`).join('')}</div>`;
}

function affiliateNote() {
  return `<div class="affiliate-notice" role="note"><strong>Affiliate disclosure:</strong> Countryman Travels may earn a commission if you book through commercial links on this page, at no additional cost to you. Recommendations are independently selected. <a href="/affiliate-disclosure.html">How our links work</a>.</div>`;
}

function photoFigure({ src, alt, photographer, sourceName, sourceUrl, license, licenseUrl, className = 'dw-photo-band' }) {
  const loading = className === 'dw-hero-photo' ? 'loading="eager" fetchpriority="high"' : 'loading="lazy"';
  return `<figure class="${className}"><img src="${src}" alt="${alt}" ${loading} decoding="async"><figcaption>Photo: <a href="${sourceUrl}" target="_blank" rel="noopener">${photographer}</a> / ${sourceName} · <a href="${licenseUrl}" target="_blank" rel="license noopener">${license}</a> · <a href="/orlando/disney-world/photo-credits.html">Credits</a></figcaption></figure>`;
}

